final(10,1,'هم‌ایستایی','true_false','درستی عبارت را تعیین کنید و اگر نادرست است آن را اصلاح کنید: «در هم‌ایستایی، همهٔ کمیت‌های محیط درونی در تمام لحظه‌ها بدون کوچک‌ترین نوسان ثابت می‌مانند.»','نادرست است. هم‌ایستایی حفظ ثبات نسبی محیط درونی در محدودهٔ مناسب است؛ تغییرات محدود و پاسخ‌های تنظیمی می‌توانند وجود داشته باشند.', [('تشخیص نادرست‌بودن عبارت',0.5),('جایگزینی ثبات مطلق با ثبات نسبی در محدودهٔ مناسب',0.5)],truth=False)
final(10,1,'سازمان‌یابی زیستی','definition_comparison','«جمعیت» و «بوم‌سازگان» را مقایسه کنید و توضیح دهید چرا بررسی هم‌زمان ماهی‌ها، گیاهان و دمای یک برکه فقط بررسی یک جمعیت نیست.','جمعیت گروهی از افراد یک گونه در زمان و مکان مشخص است. بوم‌سازگان جانداران یک ناحیه، عوامل غیرزنده و ارتباط آن‌ها را دربرمی‌گیرد. مثال برکه چند گروه جاندار و عامل غیرزندهٔ دما را شامل می‌شود.', [('تعریف جمعیت با افراد یک گونه و زمان/مکان مشخص',0.5),('ذکر جانداران و عوامل غیرزنده و ارتباط‌ها در بوم‌سازگان',0.5),('استفاده از تنوع جانداران و دمای برکه در استدلال',0.5)])
final(10,1,'طراحی پژوهش','essay','می‌خواهیم اثر شوری آب بر درصد جوانه‌زنی بذر تربچه را بررسی کنیم. طرح کوتاهی بنویسید که گروه شاهد، عامل تغییریافته، دو عامل ثابت، روش گزارش نتیجه و یک راه افزایش اعتبار مقایسه را روشن کند.','دو یا چند گروه بذر هم‌نوع با شرایط اولیهٔ مشابه انتخاب می‌کنیم. شاهد آب بدون نمک افزوده دریافت می‌کند و گروه آزمایشی محلول با شوری مشخص. دما، نور، تعداد و نوع بذر و مدت بررسی یکسان می‌مانند. درصد جوانه‌زنی از تقسیم تعداد بذر جوانه‌زده بر کل بذرها و ضرب در صد محاسبه و پس از زمان یکسان مقایسه می‌شود؛ تکرار آزمایش اعتبار را بیشتر می‌کند.', [('شاهد و شوری مشخص در گروه آزمایشی',0.5),('ذکر دست‌کم دو عامل ثابت مناسب',0.5),('شمارش و محاسبه/گزارش درصد پس از زمان یکسان',0.5),('تکرار یا استفاده از چند بذر برای کاهش اثر تفاوت فردی',0.5)])

final(10,2,'گوارش و جذب','fill_blank','جاهای خالی را کامل کنید: شکستن مولکول‌های غذا به واحدهای کوچک‌تر را .......... و ورود مواد گوارش‌یافته از پوشش روده به محیط درونی را .......... می‌نامیم.','گوارش شیمیایی؛ جذب.', [('گوارش شیمیایی برای شکستن مولکول‌ها',0.5),('جذب برای ورود از سد پوششی به محیط درونی',0.5)])
final(10,2,'سطح جذب','short','چرا کاهش سطح پرزهای رودهٔ باریک، حتی با ترشح کافی آنزیم‌ها، می‌تواند جذب مواد غذایی را کم کند؟','آنزیم‌ها گوارش شیمیایی را انجام می‌دهند، اما عبور فرآورده‌ها به محیط درونی به سطح جذب نیاز دارد. پرزها سطح تماس را افزایش می‌دهند و آسیب آن‌ها سطح مؤثر جذب را کم می‌کند.', [('تفکیک گوارش شیمیایی از جذب',0.5),('ارتباط پرز و افزایش سطح مؤثر جذب',0.5)])
final(10,2,'اجزای گوارش','matching','هر مورد را به نقش مناسب وصل کنید؛ هر نقش یک‌بار استفاده شود. موارد: الف) صفرا، ب) لیپاز، پ) حرکات کرمی. نقش‌ها: ۱) پیش‌رانی محتویات لوله، ۲) شکستن شیمیایی چربی، ۳) ریزکردن و پخش قطره‌های چربی.','الف–۳؛ ب–۲؛ پ–۱. صفرا آنزیم نیست و با افزایش سطح تماس به عمل لیپاز کمک می‌کند.', [('تطبیق صفرا با پخش قطره‌ها',0.5),('تطبیق لیپاز با گوارش شیمیایی چربی',0.5),('تطبیق حرکات کرمی با پیش‌رانی',0.5)],promptParts=[{'id':'a','text':'صفرا'},{'id':'b','text':'لیپاز'},{'id':'c','text':'حرکات کرمی'}])

final(10,3,'انتشار گاز','diagram_label','با استفاده از نمودار فشار نسبی اکسیژن در A و B، جهت حرکت خالص اکسیژن را در صورت وجود یک سطح نازک نفوذپذیر بین آن‌ها بنویسید و توضیح دهید آیا همهٔ مولکول‌ها فقط در همان جهت حرکت می‌کنند. آیا این انتشار به مصرف مستقیم ATP نیاز دارد؟','حرکت خالص از A با فشار نسبی ۸۰ به B با فشار نسبی ۲۵ است. مولکول‌ها در هر دو جهت حرکت می‌کنند، اما در این شرایط تعداد عبوری از A به B بیشتر است. انتشار مستقیم به مصرف مستقیم ATP نیاز ندارد.', [('جهت خالص A به B با اشاره به اختلاف فشار نسبی',0.5),('تفکیک حرکت دوطرفهٔ مولکول‌ها از حرکت خالص',0.5),('نداشتن نیاز مستقیم به ATP برای انتشار',0.5)],image='diagrams/oxygen.png',imageDescription='دو ستون با برچسب‌های A و B و فشار نسبی اکسیژن به‌ترتیب ۸۰ و ۲۵، در واحد فرضی یکسان.')
final(10,3,'مکانیک تنفس','true_false','درستی عبارت را تعیین کنید و دلیل بیاورید؛ اگر نادرست است اصلاح کنید: «در دم آرام، انقباض دیافراگم با افزایش حجم قفسهٔ سینه و کاهش فشار هوای شش نسبت به بیرون همراه است.»','درست است. دیافراگم منقبض و مسطح‌تر می‌شود؛ افزایش حجم به افت فشار نسبت به بیرون و ورود هوا کمک می‌کند.', [('تشخیص درست‌بودن عبارت',0.5),('پیوند افزایش حجم با افت فشار و ورود هوا',0.5)],truth=True)
final(10,3,'آبشش و نای','definition_comparison','نقش گردش خون را در انتقال اکسیژن ماهی و حشره مقایسه کنید؛ نام سطح یا دستگاه تبادل را نیز بنویسید.','در ماهی، آبشش اکسیژن را از آب به خون می‌رساند و خون آن را به بافت‌ها منتقل می‌کند. در حشره، دستگاه نایی هوا را به نزدیکی یاخته‌ها می‌رساند و مایع گردش بدن مسیر اصلی انتقال گازهای تنفسی نیست.', [('آبشش و انتقال اکسیژن با خون در ماهی',0.5),('نای‌ها و رساندن هوا به نزدیکی یاخته‌های حشره',0.5),('تصریح تفاوت نقش گردش در انتقال گاز',0.5)])

final(10,4,'گردش عمومی و ششی','diagram_label','در طرح گردش خون، A دهلیز راست، B بطن راست، C دهلیز چپ و D بطن چپ است. مسیر بازگشت خون از شش تا خروج به بدن را با حروف بنویسید و نقش دریچه‌های قلب را در این مسیر توضیح دهید.','شش‌ها → C → D → بدن. خون ششی ابتدا به دهلیز چپ و سپس بطن چپ وارد می‌شود؛ بطن چپ آن را به گردش عمومی می‌فرستد. دریچه‌ها در پاسخ به اختلاف فشار باز و بسته می‌شوند و از بازگشت نامناسب خون جلوگیری می‌کنند.', [('ترتیب شش‌ها، C، D و بدن',1),('کارکرد یک‌طرفه‌کردن عبور و جلوگیری از برگشت',0.5),('ارتباط باز و بسته‌شدن با اختلاف فشار',0.5)],image='diagrams/circulation.png',imageDescription='طرح غیرتشریحی مسیر دو گردش با چهار حفرهٔ A تا D، شش‌ها و بدن.')
final(10,4,'لنف','short','در ناحیه‌ای، تخلیهٔ لنف کم شده ولی ورود مایع از مویرگ‌ها به فضای میان‌بافتی ادامه دارد. علت ایجاد تورم را توضیح دهید.','بخشی از مایع میان‌بافتی به‌طور معمول از راه رگ‌های لنفی به خون بازمی‌گردد. کاهش تخلیهٔ لنف باعث می‌شود ورود مایع از خروج آن بیشتر و مایع در فضای میان یاخته‌ها جمع شود.', [('نقش لنف در بازگرداندن مایع میان‌بافتی',0.5),('ارتباط کاهش خروج و تجمع مایع با تورم',0.5)])
final(10,4,'رگ‌های خونی','matching','رگ‌ها را با ویژگی مناسب تطبیق دهید: الف) سرخرگ، ب) سیاهرگ، پ) مویرگ. ویژگی‌ها: ۱) دیوارهٔ بسیار نازک برای تبادل، ۲) بازگرداندن خون به قلب، ۳) بردن خون از قلب با دیوارهٔ متناسب با فشار بالاتر.','الف–۳؛ ب–۲؛ پ–۱. ملاک نام‌گذاری سرخرگ و سیاهرگ جهت حرکت نسبت به قلب است، نه مقدار اکسیژن.', [('سرخرگ و خروج از قلب',0.5),('سیاهرگ و بازگشت به قلب',0.5),('مویرگ و تبادل از دیوارهٔ نازک',0.5)],promptParts=[{'id':'a','text':'سرخرگ'},{'id':'b','text':'سیاهرگ'},{'id':'c','text':'مویرگ'}])

final(10,5,'فرایندهای نفرون','definition_comparison','بازجذب و ترشح را از نظر جهت جابه‌جایی ماده میان خون و لولهٔ نفرون مقایسه کنید و تفاوت آن‌ها را با تراوش کلافکی بنویسید.','بازجذب بازگشت ماده از مایع لوله به خون است؛ ترشح ورود ماده از خون به لوله است. تراوش کلافکی عبور بخشی از مایع خون و مواد کوچک از صافی کلافک به درون کپسول است و به این محل ویژه مربوط می‌شود.', [('جهت صحیح بازجذب',0.5),('جهت صحیح ترشح',0.5),('محل و جهت تراوش کلافکی',0.5)])
final(10,5,'تنظیم آب','fill_blank','پس از کم‌آبی، افزایش هورمون .......... معمولاً بازجذب آب را بیشتر می‌کند؛ در نتیجه حجم ادرار معمولاً .......... می‌یابد.','ضدادراری؛ کاهش.', [('هورمون ضدادراری/ADH',0.5),('کاهش حجم ادرار',0.5)])
final(10,5,'ادرار نهایی','essay','در فرد سالم، گلوکز می‌تواند در مایع تراوش‌شده وجود داشته باشد، ولی در ادرار نهایی مقدار قابل توجهی از آن دیده نمی‌شود. این وضعیت را با دو مرحلهٔ نفرون توضیح دهید؛ آیا از نبود گلوکز در ادرار می‌توان نبود آن در خون را نتیجه گرفت؟','گلوکز مادهٔ کوچکی است و می‌تواند از صافی کلافک عبور کند. در شرایط طبیعی، گلوکز تراوش‌شده در طول نفرون تقریباً به‌طور کامل به خون بازجذب می‌شود. بنابراین نبود مقدار قابل توجه آن در ادرار به معنی نبود گلوکز در خون یا تراوش‌نشدن آن نیست.', [('عبور گلوکز در تراوش',0.5),('بازجذب تقریباً کامل در شرایط طبیعی',0.5),('رد استنتاج نبود گلوکز در خون از ادرار',0.5)])

final(10,6,'یاختهٔ گیاهی','true_false','درستی عبارت را تعیین و اصلاح کنید: «دیوارهٔ یاختهٔ گیاهی چون از ترکیدن یاخته جلوگیری می‌کند، کاملاً مانع ورود آب به آن می‌شود.»','نادرست است. آب از دیواره و غشای یاختهٔ گیاهی عبور می‌کند. ورود آب فشار تورژسانس ایجاد می‌کند و مقاومت دیواره افزایش نامحدود حجم را محدود می‌سازد؛ جلوگیری از ترکیدن به معنی جلوگیری کامل از ورود آب نیست.', [('تشخیص نادرست‌بودن',0.5),('امکان ورود آب و نقش مقاومت دیواره/تورژسانس',1)],truth=False)
final(10,6,'بافت نگهدارنده','definition_comparison','کلانشیم و اسکلرانشیم را از نظر زنده‌بودن معمول یاختهٔ بالغ و ویژگی دیواره مقایسه کنید و بگویید کدام‌یک برای پشتیبانی اندام در حال رشد مناسب‌تر است.','کلانشیم معمولاً یاخته‌های زنده با دیوارهٔ نخستین نامساوی‌ضخیم دارد و همراه رشد اندام انعطاف بیشتری نشان می‌دهد. یاخته‌های اسکلرانشیم در بلوغ معمولاً مرده و دارای دیوارهٔ پسین ضخیم و اغلب چوبی‌اند. برای پشتیبانی بخش جوانِ در حال رشد، کلانشیم مناسب‌تر است.', [('زنده‌بودن و دیوارهٔ نخستین کلانشیم',0.5),('مرگ معمول و دیوارهٔ پسین ضخیم اسکلرانشیم',0.5),('انتخاب کلانشیم با دلیل سازگاری با رشد',0.5)])
final(10,6,'ارتباط یاخته‌ای','short','چرا وجود دیواره میان دو یاختهٔ گیاهی به معنی قطع کامل ارتباط سیتوپلاسمی آن‌ها نیست؟ نام راه ارتباطی را بنویسید.','پلاسمودسم‌ها راه‌های باریکی از میان دیواره‌اند که ارتباط سیتوپلاسمی یاخته‌های مجاور را برقرار می‌کنند؛ بنابراین وجود دیواره ارتباط را به‌طور کامل قطع نمی‌کند.', [('نام پلاسمودسم',0.5),('توضیح ارتباط سیتوپلاسمی از میان دیواره',0.5)])

final(10,7,'انتقال شیره','fill_blank','برگ بالغِ صادرکنندهٔ قند یک .......... و میوهٔ در حال رشدِ دریافت‌کنندهٔ آن یک .......... است؛ مسیر عمدهٔ انتقال قند آوند .......... است.','منبع؛ مخزن؛ آبکش.', [('منبع برای برگ صادرکننده',0.5),('مخزن برای میوهٔ دریافت‌کننده',0.5),('آبکش برای انتقال قند',0.5)])
final(10,7,'جذب اسمزی','essay','چرا یک گیاه می‌تواند در خاک مرطوبِ بسیار شور پژمرده شود؟ پاسخ را با حرکت اسمزی آب و وضعیت یاخته‌های ریشه مرتبط کنید.','وجود آب در خاک به‌تنهایی جذب آن را تضمین نمی‌کند. افزایش زیاد غلظت محلول بیرونی می‌تواند اختلاف اسمزیِ مساعد ورود آب را کم کند یا موجب خروج آب از یاخته‌های ریشه شود. کاهش آب و فشار تورژسانس در بافت‌ها به پژمردگی می‌انجامد.', [('تفکیک وجود آب از امکان جذب',0.5),('کاهش ورود یا خروج اسمزی آب در شوری زیاد',0.5),('پیوند کاهش آب/تورژسانس با پژمردگی',0.5)])
final(10,7,'نوار کاسپاری','short','آبی که در مسیر دیواره‌ای پوست ریشه پیش می‌رود، در درون‌پوست چگونه تحت گزینش غشایی قرار می‌گیرد؟','نوار کاسپاری مسیر دیواره‌ای را مسدود می‌کند. آب و مواد این مسیر برای ادامه به استوانهٔ آوندی باید از غشای یاختهٔ درون‌پوست عبور کنند؛ تراوایی انتخابی غشا امکان کنترل ورود مواد را فراهم می‌کند.', [('مسدودشدن مسیر دیواره‌ای توسط نوار کاسپاری',0.5),('لزوم عبور از غشا و نقش گزینشی آن',0.5)])
